WITH base AS (SELECT *, UPPER(channel) AS channel_upper, DATEDIFF(starts_on, ends_on) / 7 AS weeks_ends_on_to_starts_on, COALESCE(channel, 'UNKNOWN') AS resolved_channel FROM promotions WHERE ends_on >= DATE '2023-09-09' AND ends_on > '2024-08-01'), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY weeks_ends_on_to_starts_on, id) AS dedup_rank FROM base) x WHERE dedup_rank = 1), enriched AS (SELECT *, DENSE_RANK() OVER (ORDER BY discount_pct) AS discount_pct_dense_rank, LAG(discount_pct, 1) OVER (PARTITION BY YEAR(starts_on), promo_code ORDER BY ends_on, id) AS prev_discount_pct FROM latest WHERE channel NOT IN ('mobile', 'partner')), with_windows AS (SELECT *, FIRST_VALUE(prev_discount_pct, TRUE) OVER (PARTITION BY DATE_TRUNC('WEEK', ends_on), channel ORDER BY weeks_ends_on_to_starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_prev_discount_pct, ROUND(prev_discount_pct / SUM(prev_discount_pct) OVER (PARTITION BY promo_code, channel), 4) AS prev_discount_pct_share, ROW_NUMBER() OVER w_recent AS row_seq FROM enriched WINDOW w_recent AS (PARTITION BY YEAR(ends_on), channel ORDER BY weeks_ends_on_to_starts_on DESC, id)), matched AS (SELECT e.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM with_windows e LEFT JOIN promotions pr ON e.channel <=> pr.channel AND e.starts_on >= pr.starts_on AND e.starts_on <= DATE_ADD(pr.ends_on, 3)) SELECT id, channel, promo_code, starts_on, ends_on, channel_upper, resolved_channel, dedup_rank, discount_pct_dense_rank FROM matched
